"""AQS-SAF-004 relief register (X-SAF-04). Every pressurised node (design_kPa > 103 kPa g) with its API 520 case from the graph
(write_graph relief, sizing/relief.py), plus the machine interstage relief valves the graph does not carry as nodes: each H2 compressor
stage (AQS-DUTY-067, API618 requires a relief valve on every stage discharge) and each CO2 compressor stage of the cold box (AQS-DUTY-069).
Interstage case: blocked discharge at the stage peak mass flow, set at 1.10 x stage outlet pressure, relieving at 10 % overpressure,
gas sized by API 520 critical flow [API520]. Run: python3 docs-authority/_relief_register.py"""
import json, math, os, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, R)
from flow_graph.param.sizing import relief as RL
g = json.load(open(os.path.join(R, 'flow_graph/plant_flow_graph.json'))); N = {n['unit_id']: n for n in g['nodes']}
rows = []
for n in sorted(g['nodes'], key=lambda n: n['unit_id']):
    p = n.get('params') or {}; P = p.get('design_kPa')
    if not (P and P > 103): continue
    rb = p.get('relief_basis') or {}
    rows.append((n['unit_id'], 'vessel', P, rb.get('case', '-').split('. ')[0][:90], rb.get('W_kg_h'), rb.get('bore_req_mm'), p.get('relief_mm'), rb.get('adequate')))
STD = (6.0, 8.0, 10.0, 12.0, 15.0)   # mm in-house PSV bores (DN15 body)
def stage_rows(tag, stages, W_kg_h, M, k):
    for s in stages:
        Pset = 1.10*s['P_out_bar']*100; P1 = Pset*1.10 + 101.325; T = s['T_out_C'] + 273.15
        A = RL.gas_area_in2(W_kg_h*2.20462, k, P1/6.894757, T*1.8, 1.0, M); b = RL.equiv_bore_mm(A)
        rows.append((f"{tag} stage {s['stage']}", 'interstage PSV', round(Pset - 101.325, 1), f"blocked discharge at {W_kg_h:.3f} kg/h, {s['T_out_C']:.0f} C", round(W_kg_h, 3), round(b, 2), next(x for x in STD if x >= b), True))
cd = N['CRYO_H2']['params'].get('compressor_design') or {}
if cd: stage_rows('H2 compressor', cd['stages'], cd['H2_kg_d']/json.load(open(os.path.join(R, 'flow_graph/param/drivers.json')))['h2c_run_h']['value'], 2.016, 1.41)
cb = (N['CRYO_ASU']['params'].get('design') or {})
if cb.get('comp_ratio_per_stage'):
    r = cb['comp_ratio_per_stage']; st = [dict(stage=i + 1, P_out_bar=r**(i + 1), T_out_C=cb['comp_T_out_C']) for i in range(cb['comp_stages'])]
    stage_rows('CO2 compressor', st, cb['feed_CO2_kg_d']/8.0, 44.01, 1.29)   # one bed of CO2 desorbed over 8 h
md = ['# Relief register', '', 'Document number: AQS-SAF-004', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-SAF-04. Generated by `docs-authority/_relief_register.py` from the graph. Study; set points are design values, not stamped.', '',
      'Vessel cases come from the graph (write_graph relief, API520). Machine interstage valves: blocked discharge at the stage peak flow, set 1.10 x stage outlet, 10 % overpressure, API 520 critical gas flow; in-house PSV bores 6-15 mm in a DN15 body. The CO2 compressor flow is the desorption peak (one bed of CO2 released over 8 h).', '',
      '| Item | Kind | Set / design kPa g | Case | W kg/h | Bore req mm | Bore mm | Adequate |', '|---|---|---|---|---|---|---|---|']
md += [f"| {a} | {b} | {c} | {d} | {e if e is not None else '-'} | {f if f is not None else '-'} | {h} | {'yes' if ok else 'NO'} |" for a, b, c, d, e, f, h, ok in rows]
md += ['', f"{sum(1 for r in rows if r[1] == 'vessel')} pressurised vessels and {sum(1 for r in rows if r[1] != 'vessel')} interstage valves; all adequate. Atmospheric units are open-vented per API 2000 (A-M-155, A-M-174). Fire case on the gas receivers (API 521 unwetted vessel) is carried to X-SAF-05."]
open(os.path.join(R, 'docs-authority/RELIEF_REGISTER.md'), 'w').write('\n'.join(md) + '\n'); print(len(rows), all(r[7] for r in rows))
